fn dims() -> i32 {
    (320 << 16) | 240
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x102030);
    host::display::fill_rect(0, 0, w, 2, 0xffffff);
    host::display::fill_rect(0, h - 2, w, 2, 0xffffff);
    host::display::fill_rect(0, 0, 2, h, 0xffffff);
    host::display::fill_rect(w - 2, 0, 2, h, 0xffffff);
    host::display::draw_string(8, 8, "DIMS", 0x808080, 1);
    host::display::draw_number(8, 24, w, 0xffffff, 2);
    host::display::draw_number(8, 48, h, 0xffffff, 2);
    host::display::present();
}
